const inputData = input.config();  // Store all input data in a single constant
let recordId = inputData.recordID;
let convoHistory = inputData.convohistory;
let leadID = inputData.leadID;
let workspaceID = inputData.workspaceID;
let campaignID = inputData.campaignID;

let tableEmails = base.getTable("Emails");
let tableCampaigns = base.getTable("Campaigns");

const apiKey = 'Bearer REDACTED';

// Switch to desired workspace
async function switchWorkspace(workspaceID) {
    const url = 'https://send.dulcy.io/api/workspaces/v1.1/switch-workspace';
    const options = {
        method: 'POST',
        headers: {
            'Authorization': apiKey,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ team_id: workspaceID })
    };

    const response = await fetch(url, options);
    const resJson = await response.json();
    console.log("Workspace switch response:", resJson);

    if (!response.ok) {
        throw new Error(`Failed to switch workspace: ${response.status}`);
    }

    console.log(`Switched to workspace ID: ${workspaceID}`);
}

// Get tag ID by name (case-insensitive)
async function getTagID(tagName) {
    const url = 'https://send.dulcy.io/api/tags';
    const options = {
        method: 'GET',
        headers: {
            'Authorization': apiKey,
            'Content-Type': 'application/json'
        }
    };

    const response = await fetch(url, options);
    const data = await response.json();

    if (!response.ok) {
        throw new Error(`Failed to fetch tags: ${response.status}`);
    }

    const tagList = data.data;
    console.log("Available tags:", tagList.map(t => t.name));

    const tag = tagList.find(t =>
        t.name.trim().toLowerCase() === tagName.trim().toLowerCase()
    );

    if (!tag) {
        throw new Error(`Tag "${tagName}" not found in current workspace`);
    }

    return tag.id;
}

// Attach tag to lead
async function attachTagToLead(tagID, leadID) {
    const url = 'https://send.dulcy.io/api/tags/attach-to-leads';
    const body = {
        tag_ids: [tagID],
        lead_ids: [leadID]
    };

    const options = {
        method: 'POST',
        headers: {
            'Authorization': apiKey,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
    };

    const response = await fetch(url, options);
    if (!response.ok) {
        throw new Error(`Failed to attach tag: ${response.status}`);
    }

    console.log(`Tag ${tagID} attached to lead ${leadID}`);
}

// Increment Meetings Booked in Campaigns table
async function incrementMeetingsBooked(campaignID) {
    try {
        const existingRecords = await tableCampaigns.selectRecordsAsync();
        const campaignRecord = existingRecords.records.find(record => `${record.getCellValue("ID")}` === `${campaignID}`);

        if (campaignRecord) {
            const current = campaignRecord.getCellValue("Meetings Booked") || 0;
            await tableCampaigns.updateRecordAsync(campaignRecord.id, {
                "Meetings Booked": current + 1
            });
            console.log(`Incremented Meetings Booked for Campaign ID ${campaignID}`);
        } else {
            console.error(`Campaign with ID ${campaignID} not found`);
        }
    } catch (error) {
        console.error(`Error incrementing Meetings Booked: ${error.message}`);
    }
}

// MAIN FUNCTION
(async function () {
    try {
        await switchWorkspace(workspaceID);

        const tagID = await getTagID("Meeting Booked");

        if (recordId) {
            const record = await tableEmails.selectRecordAsync(recordId);
            const webhookUrl = "https://hook.us1.make.com/REDACTED_PATH";

            const payload = {
                "Leads Name": record.getCellValue("Leads Name"),
                "Leads Email": record.getCellValue("Leads Email"),
                "Campaign Name": record.getCellValue("Campaign Name"),
                "Conversation History": convoHistory || "No conversation history available",
                "Workspace ID": inputData.workspaceID,
                "Status": "WON"
            };

            await fetch(webhookUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            console.log(`Webhook sent for Lead: ${record.getCellValue("Leads Name")}`);

            await attachTagToLead(tagID, leadID);
            await incrementMeetingsBooked(campaignID);
        } else {
            console.warn("No record ID provided.");
        }
    } catch (error) {
        console.error("Error:", error.message);
    }
})();

const inputData = input.config();

const recordId = inputData.recordID;
const convoHistory = inputData.convohistory;
const workspaceID = inputData.workspaceID;

let tableEmails = base.getTable("Emails");

// MAIN FUNCTION
(async function () {
  try {
    if (!recordId) {
      console.warn("No record ID provided.");
      return;
    }

    const record = await tableEmails.selectRecordAsync(recordId);
    const webhookUrl = "https://hook.us1.make.com/REDACTED_PATH";

    const payload = {
      "Leads Name": record.getCellValue("Leads Name"),
      "Leads Email": record.getCellValue("Leads Email"),
      "Campaign Name": record.getCellValue("Campaign Name"),
      "Conversation History": convoHistory || "No conversation history available",
      "Workspace ID": workspaceID,
      "Status": "LOST"

    };

    await fetch(webhookUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    console.log("Webhook sent successfully:", payload);

  } catch (error) {
    console.error("Webhook error:", error.message);
  }
})();
